package site.cadera.arunika.dungeon.shared;
import java.time.*;
import java.util.*;
import java.nio.file.*;
import site.cadera.arunika.dungeon.core.SessionRegistry;
import static site.cadera.arunika.dungeon.core.SessionRegistry.Mode.*;

public final class SharedTest {
 static int count;static void ok(boolean x,String why){if(!x)throw new AssertionError(why);count++;System.out.println("PASS "+why);} static void rejects(Runnable r,String why){try{r.run();}catch(RuntimeException e){ok(true,why);return;}throw new AssertionError(why);}
 static final class Time extends Clock {Instant t=Instant.parse("2026-11-21T00:00:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return t;}void add(long s){t=t.plusSeconds(s);}}
 static SessionRegistry reg(Time t){return new SessionRegistry(Set.of("bee","warden"),5,3,Duration.ofMinutes(30),Duration.ofSeconds(60),t);}
 static final class Port implements SharedQueue.Port {final SessionRegistry reg;Set<UUID> offline=new HashSet<>();Set<UUID> dead=new HashSet<>();boolean ready=true,fail;final List<SessionRegistry.Session> runs=new ArrayList<>();Port(SessionRegistry r){reg=r;}public boolean eligible(UUID p,String f){return !offline.contains(p);}public boolean ready(String f){return ready;}public void start(SessionRegistry.Session s){if(fail)throw new IllegalStateException("teleport failed");reg.activate(s.id());runs.add(s);}public Set<UUID> living(SessionRegistry.Session s){Set<UUID> x=new HashSet<>(s.participants());x.removeAll(dead);return x;}}
 static SharedQueue.View view(SharedQueue q,String f,long now){return q.views(now,true).stream().filter(v->v.floor().equals(f)).findFirst().orElseThrow();}
 public static void main(String[] args)throws Exception{
  Time t=new Time();var r=reg(t);var p=new Port(r);var q=new SharedQueue(r,Map.of("bee",30,"warden",5),p);UUID a=UUID.randomUUID(), b=UUID.randomUUID(), c=UUID.randomUUID();
  q.join("bee",a);rejects(()->q.join("warden",a),"cannot queue two floors");rejects(()->r.reserve("bee",PRIVATE,a,Set.of(a)),"queue locks private reservation");q.join("warden",b);q.tick(0,true);ok(view(q,"bee",0).seconds()==30,"independent 30-second countdown");ok(view(q,"warden",0).seconds()==5,"per-floor countdown overrides");
  q.tick(5000,true);ok(p.runs.size()==1&&p.runs.getFirst().floor().equals("warden"),"warden starts independently");rejects(()->q.join("bee",b),"active participant cannot queue");
  for(int i=0;i<150;i++)q.join("bee",UUID.randomUUID());q.tick(29000,true);q.join("bee",c);q.tick(30000,true);var bee=p.runs.stream().filter(s->s.floor().equals("bee")).findFirst().orElseThrow();ok(bee.participants().size()==152,"152 simultaneous participants; no dungeon cap");ok(view(q,"bee",30000).queued().isEmpty(),"queue consumed atomically");ok(r.queuedFloor(a).isEmpty()&&r.participant(a).isPresent(),"queue -> active tracking");p.dead.add(a);ok(view(q,"bee",30000).living().size()==151,"living participant snapshot");
  UUID late=UUID.randomUUID();q.join("bee",late);ok(view(q,"bee",30000).queued().equals(List.of(late)),"late join waits next run");
  Path dir=Files.createTempDirectory("adg-cd-test");Path data=dir.resolve("shared-cooldowns.txt");var store=new CooldownStore(data);ok(store.load().isEmpty(),"new store empty");r.setCooldownSink(store::save);t.add(100);r.bossDefeated(bee.id());ok(view(q,"bee",30000).state()==SharedQueue.State.LOOT&&view(q,"bee",30000).seconds()==1800,"live status shows loot and running cooldown");q.tick(30001,true);ok(p.runs.size()==2&&r.participant(a).isPresent(),"queue blocked while loot phase holds arena");r.close(bee.id());ok(r.remaining("bee").toSeconds()==1800,"30 minutes from actual boss kill");ok(r.remaining("warden").isZero(),"other floor unaffected");rejects(()->r.bossDefeated(bee.id()),"duplicate kill rejected");ok(view(q,"bee",30000).state()==SharedQueue.State.COOLDOWN,"queued during cooldown");q.tick(40000,true);ok(p.runs.size()==2,"cooldown prevents start");
  var privateRun=r.reserve("bee",PRIVATE,UUID.fromString("00000000-0000-0000-0000-000000000001"),Set.of(UUID.fromString("00000000-0000-0000-0000-000000000001")));r.activate(privateRun.id());r.bossDefeated(privateRun.id());r.close(privateRun.id());ok(r.remaining("bee").toSeconds()==1800,"private kill doesn't reset shared cooldown");
  t.add(600);var restarted=reg(t);restarted.restoreCooldowns(store.load());ok(restarted.remaining("bee").toSeconds()==1200,"restart retains remaining cooldown");t.add(1200);var restarted2=reg(t);restarted2.restoreCooldowns(store.load());ok(restarted2.remaining("bee").isZero(),"expired persisted cooldown ignored");
  q.tick(50000,false);ok(q.views(50000,false).stream().filter(v->v.floor().equals("bee")).findFirst().orElseThrow().state()==SharedQueue.State.PAUSED,"no countdown while performance guard blocks");q.tick(51000,true);ok(view(q,"bee",51000).seconds()==30,"countdown starts after cooldown and guard");p.fail=true;q.tick(81000,true);ok(r.queuedFloor(late).orElseThrow().equals("bee")&&r.participant(late).isEmpty(),"failed start restores queue and unlocks session");ok(view(q,"bee",81000).state()==SharedQueue.State.PAUSED,"retry backoff");p.fail=false;q.tick(91000,true);q.tick(121000,true);ok(r.participant(late).isPresent(),"retry starts once");
  UUID d=UUID.randomUUID();q.join("warden",d);p.offline.add(d);q.tick(122000,true);ok(r.queuedFloor(d).isEmpty(),"disconnect removes queue registration");UUID e=UUID.randomUUID();q.join("warden",e);ok(q.leave(e)&&r.queuedFloor(e).isEmpty(),"explicit queue leave unlocks UUID");q.join("warden",e);q.clear();ok(q.empty()&&r.queuedFloor(e).isEmpty(),"shutdown clears transient queues");
  r.setCooldownSink(v->{throw new java.io.IOException("disk failure");});rejects(()->r.bossDefeated(r.participant(late).orElseThrow().id()),"persistence failure surfaced");ok(!r.storageHealthy(),"disk failure locks Shared");rejects(()->r.enqueue("bee",UUID.randomUUID()),"fail closed after disk error");
  Files.writeString(data,"bad data");try{store.load();throw new AssertionError("corrupt store accepted");}catch(java.io.IOException expected){ok(true,"corrupt store rejected");}Files.delete(data);Files.delete(dir);
  System.out.println("Shared tests passed: "+count);
 }
}
